import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/22-成人的“安全基地”.md","filePath":"books/attached/22-成人的“安全基地”.md","lastUpdated":1794316978000}'),n={name:"books/attached/22-成人的“安全基地”.md"};function d(l,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"成人的-安全基地",tabindex:"-1"},[s("成人的“安全基地” "),e("a",{class:"header-anchor",href:"#成人的-安全基地","aria-label":'Permalink to "成人的“安全基地”"'},"​")],-1),e("p",null,"即使我们成人不再痴迷于玩具了，但我们还需得不断接触未知的世界，面对未知的情况，接受未知的困难。我们期待着在工作上大有所为，不仅游刃有余，还能充分激发自身的兴趣，并且基于伴侣和孩子足够的关爱。若是我们像一个母亲在场时的幼儿一样，充满着安全感，那么世界也将尽在我们掌握之中。我们将勇于冒险，富于创新，不懈地追逐梦想。但如果我们缺乏安全感呢？若是我们难以确定心爱之人是否与我们亲密，难以确认心爱的伴侣是否完全信任着我们，是否会在我们需要的时候无条件给予支持，这时候我们会发现，自己很难集中精力去面对生活的挑战。正如陌生情景测试中那样，若是我们的伴侣足够值得依靠，令人充满安全感，尤其是当他们还深谙如何在艰难的时候鼓励我们，那我们就很容易全身心投入到生活的其他领域，充分实现自我的价值。",-1),e("p",null,"卡耐基·梅隆大学亲密关系实验室的负责人布鲁克·费尼（Brooke Feeney）阐释了成人亲密关系中安全基地的工作机制。费尼博士对于成人之间如何相互支持的问题，以及影响这种支持质量高低的因素，都有着非常浓厚的兴趣。在他的一项研究中，费尼博士让伴侣们在实验室中，与对方讨论彼此的人生目标以及发展机遇问题。当参与者发现伴侣对自己的目标表示支持，在讨论后的报告中，他们会感到自尊增强，情绪也随之高涨。另外，在讨论之后，他们也认为自己实现目标的可能性更大了。而那些觉得自己的伴侣意欲干涉自己，或对自己的目标表示反对的参与者，就不再想继续阐释他们的目标，对于目标的实现与否，也变得士气低落了。他们甚至会在讨论的过程中意图降低自己的目标。",-1),e("p",null,"让我们回到真人秀恋人卡伦和蒂姆的案例中，他们的际遇与孩子在陌生情景测试中的情形，在很大程度上都非常相像，几乎是这个测试的成年人翻版。比如卡伦需要蒂姆的鼓励，蒂姆从卡伦的安抚中汲取力量，这不正像是金米希望她的妈妈在场吗？卡伦产生的阻抗行为（蒂姆不握着她的手，她就不想继续比赛了），不正像是妈妈离开之后，金米的所作所为吗？他们都需要依恋对象的安抚，否则就没法集中精力于其他的任务上。只有当“安全基地”重新建立，他们才能重新投入到其他的活动中去。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
